// Generates src/generated.ts — one typed Vue component per custom element.
import { writeFileSync } from 'node:fs';
import { eventSuffix, readComponents } from '../../../scripts/manifest.mjs';

const components = readComponents(new URL('../../elements/custom-elements.json', import.meta.url));
const camel = (s) => s.charAt(0).toLowerCase() + s.slice(1);

const lines = [
  '// Generated by scripts/generate.mjs from @orange-ui/elements/custom-elements.json. Do not edit.',
  "import { wrap } from './wrap.js';",
];
const entries = [...new Set(components.map((c) => c.entry))];
for (const e of entries) lines.push(`import '@orange-ui/elements/${e}';`);
lines.push('');
for (const c of components) {
  const props = [...new Set(c.properties.map((p) => p.name))];
  const events = c.events.map((e) => [camel(eventSuffix(e.name)), e.name]);
  lines.push(
    `/** ${c.description.split('\n')[0].replace(/\*\//g, '')} */`,
    `export const ${c.name} = wrap('${c.tag}', ${JSON.stringify(props)}, ${JSON.stringify(Object.fromEntries(events))});`,
    '',
  );
}
writeFileSync(new URL('../src/generated.ts', import.meta.url), lines.join('\n'));
console.log(`vue: ${components.length} components generated`);
